#!/usr/bin/env python3
"""
patch_table_ui.py — Chor Pulish UI patch
Replaces the old fragmented shuffle/deal/guess/result screens with a
single persistent circular table: seated players with name/avatar,
cards that shuffle at the center and deal outward to each seat, and
premium poster-style card faces (Police/Thief fixed colors, other
cards cycle a 6-color premium palette).

Usage:
    Place this script at the root of your chor-police project
    (the folder containing index.html, css/, js/) and run:

        python3 patch_table_ui.py

    It rewrites:
        index.html          (game-screen markup -> persistent table)
        css/style.css        (game-screen styles -> table/seats/cards)
        js/app.js            (rendering logic -> table-driven rendering)

    Safe to re-run: if a file was already patched, it is left untouched.
"""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent

NEW_INDEX_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">\n<title>Chor Police — Catch the Thief</title>\n<link rel="preconnect" href="https://fonts.googleapis.com">\n<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@600;700;800&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">\n<link rel="stylesheet" href="css/style.css">\n</head>\n<body>\n<div id="app">\n\n  <!-- HOME -->\n  <section id="screen-home" class="screen">\n    <div class="home-hero">\n      <div class="home-icon-cluster">🕵️🥷</div>\n      <div class="home-title">CHOR POLICE</div>\n      <div class="home-subtitle">Catch the Thief. Outsmart Everyone.</div>\n    </div>\n    <div class="home-buttons">\n      <button id="btn-play-offline" class="btn btn-primary btn-lg">🎮 PLAY OFFLINE<br><small>Play against Bots</small></button>\n      <button id="btn-play-online" class="btn btn-secondary btn-lg">🌐 PLAY WITH FRIENDS<br><small>Create / Join Room</small></button>\n    </div>\n    <div class="home-footer-links">\n      <a id="btn-how-to-play">How to Play</a>\n      <a id="btn-settings">Settings</a>\n    </div>\n  </section>\n\n  <!-- ONLINE CHOICE -->\n  <section id="screen-online-choice" class="screen">\n    <div class="top-bar"><h2>Play with Friends</h2></div>\n    <div class="home-buttons">\n      <button id="btn-online-create" class="btn btn-primary btn-lg">➕ Create Room</button>\n      <button id="btn-online-join" class="btn btn-secondary btn-lg">🔑 Join Room</button>\n      <button class="btn btn-ghost btn-back-home">← Back</button>\n    </div>\n  </section>\n\n  <!-- JOIN ROOM -->\n  <section id="screen-join" class="screen">\n    <div class="top-bar"><h2>Join Room</h2></div>\n    <div class="panel">\n      <div class="panel-title">Room Code</div>\n      <input id="join-room-code" type="text" maxlength="5" placeholder="A7K9D" style="width:100%;padding:14px;font-size:20px;letter-spacing:0.1em;text-align:center;background:var(--bg-deep);border:1px solid #2a3450;border-radius:12px;color:var(--text);text-transform:uppercase;">\n    </div>\n    <div class="panel">\n      <div class="panel-title">Your Name</div>\n      <input id="join-player-name" type="text" placeholder="Enter your name" style="width:100%;padding:14px;font-size:16px;background:var(--bg-deep);border:1px solid #2a3450;border-radius:12px;color:var(--text);">\n    </div>\n    <button id="btn-join-submit" class="btn btn-primary btn-lg">JOIN ROOM</button>\n    <button class="btn btn-ghost btn-back-home" style="margin-top:10px;">← Back</button>\n  </section>\n\n  <!-- SETUP (shared by offline + online-create) -->\n  <section id="screen-setup" class="screen">\n    <div class="top-bar"><h2 id="setup-title">Game Setup</h2></div>\n\n    <div class="panel">\n      <div class="panel-title">Number of Players (Offline only — online fills from lobby)</div>\n      <div class="stepper">\n        <button id="btn-players-minus">−</button>\n        <div class="stepper-value"><span id="players-count">4</span></div>\n        <button id="btn-players-plus">+</button>\n      </div>\n      <div class="small-note">Minimum 4 players</div>\n    </div>\n\n    <div class="panel">\n      <div class="panel-title">Number of Rounds</div>\n      <div class="stepper">\n        <button id="btn-rounds-minus">−</button>\n        <div class="stepper-value"><span id="rounds-count">5</span></div>\n        <button id="btn-rounds-plus">+</button>\n      </div>\n    </div>\n\n    <div class="panel">\n      <div class="panel-title">Cards &amp; Values</div>\n      <div id="card-list"></div>\n      <div class="add-card-form">\n        <input id="new-card-name" type="text" placeholder="Card name">\n        <input id="new-card-value" type="number" placeholder="Value">\n        <input id="new-card-icon" type="text" placeholder="🎴">\n      </div>\n      <button id="btn-add-card" class="btn btn-secondary" style="margin-top:10px;">+ ADD NEW CARD</button>\n    </div>\n\n    <div class="panel">\n      <div class="panel-title">Police Reward Points</div>\n      <input id="police-reward" type="number" value="100" style="width:100%;padding:12px;background:var(--bg-deep);border:1px solid #2a3450;border-radius:10px;color:var(--text);">\n      <div class="small-note">Points transferred between Police and Thief when the round resolves.</div>\n    </div>\n\n    <div id="setup-online-only" class="panel" style="display:none;">\n      <div class="panel-title">Your Name (Host)</div>\n      <input id="host-name-input" type="text" placeholder="Your name" onchange="App.playerName=this.value" style="width:100%;padding:12px;background:var(--bg-deep);border:1px solid #2a3450;border-radius:10px;color:var(--text);">\n    </div>\n\n    <div class="panel">\n      <div class="panel-title">Other Settings</div>\n      <div class="toggle-row"><span>3D Animations</span><input id="toggle-3d" type="checkbox" checked></div>\n      <div class="toggle-row"><span>Sound Effects</span><input id="toggle-sfx" type="checkbox" checked></div>\n      <div class="toggle-row"><span>Background Music</span><input id="toggle-music" type="checkbox" checked></div>\n      <div class="toggle-row"><span>Bot Difficulty</span>\n        <select id="bot-difficulty" style="background:var(--bg-deep);color:var(--text);border:1px solid #2a3450;border-radius:8px;padding:6px;">\n          <option value="easy">Easy</option>\n          <option value="normal" selected>Normal</option>\n          <option value="hard">Hard</option>\n        </select>\n      </div>\n    </div>\n\n    <button id="btn-setup-continue" class="btn btn-primary btn-lg">CONTINUE</button>\n    <button class="btn btn-ghost btn-back-home" style="margin-top:10px;">← Back</button>\n  </section>\n\n  <!-- LOBBY (online) -->\n  <section id="screen-lobby" class="screen">\n    <div class="top-bar"><h2>Room Lobby</h2></div>\n    <div class="panel room-code-display">\n      <div class="small-note">ROOM CODE</div>\n      <div class="code" id="lobby-room-code">-----</div>\n      <button id="btn-lobby-copy" class="btn btn-secondary" style="margin-top:10px;width:auto;padding:10px 18px;">Copy Code</button>\n    </div>\n    <div class="panel">\n      <div class="panel-title">Players <span id="lobby-players-count"></span> · Rounds <span id="lobby-rounds"></span></div>\n      <div id="lobby-player-list"></div>\n    </div>\n    <button id="btn-lobby-start" class="btn btn-primary btn-lg">START GAME</button>\n    <div id="lobby-waiting-text" class="small-note" style="text-align:center;margin-top:10px;">Waiting for the host...</div>\n    <button id="btn-lobby-leave" class="btn btn-ghost" style="margin-top:10px;">Leave Room</button>\n  </section>\n\n  <!-- GAME SCREEN -->\n  <section id="screen-game" class="screen">\n\n    <!-- Persistent circular table — shuffle, deal, reveal, guess and\n         result all happen on this one board instead of separate stages. -->\n    <div id="stage-table" class="stage active">\n      <div class="round-banner" id="round-banner">ROUND 1 / 5</div>\n\n      <div class="table-arena">\n        <div class="table-felt">\n          <div class="table-felt-inner"></div>\n          <div class="seats-ring" id="seats-ring"></div>\n          <div class="table-center" id="table-center">\n            <div class="center-deck" id="center-deck">\n              <div class="deck-card"></div><div class="deck-card"></div><div class="deck-card"></div>\n            </div>\n            <div class="center-plaque" id="center-plaque"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <div id="round-sheet" class="round-sheet">\n      <div class="round-sheet-inner">\n        <div class="panel-title" id="scoreboard-title">ROUND RESULTS</div>\n        <div id="scoreboard-list"></div>\n      </div>\n    </div>\n\n    <div id="stage-final" class="stage">\n      <div class="final-winner" id="final-winner"></div>\n      <div id="final-list"></div>\n      <div class="btn-row" style="margin-top:20px;">\n        <button id="btn-play-again" class="btn btn-primary">PLAY AGAIN</button>\n        <button id="btn-final-home" class="btn btn-secondary">HOME</button>\n      </div>\n    </div>\n  </section>\n\n  <!-- GUESS CONFIRM MODAL (shared) -->\n  <div id="guess-confirm" class="guess-confirm-modal">\n    <div class="guess-confirm-sheet">\n      <h3>Are you sure?</h3>\n      <p class="small-note">Accuse <strong><span id="confirm-suspect-name"></span></strong> of being the Thief?</p>\n      <div class="btn-row" style="margin-top:16px;">\n        <button id="btn-catch-him" class="btn btn-primary">CATCH HIM</button>\n        <button id="btn-cancel-guess" class="btn btn-secondary">CANCEL</button>\n      </div>\n    </div>\n  </div>\n\n  <!-- HOW TO PLAY -->\n  <section id="screen-how-to-play" class="screen">\n    <div class="top-bar"><h2>How to Play</h2></div>\n    <div class="step-card"><div class="step-num">1</div><div class="step-text">Everyone receives one hidden card.</div></div>\n    <div class="step-card"><div class="step-num">2</div><div class="step-text">Whoever holds the Police card becomes the Police for the round.</div></div>\n    <div class="step-card"><div class="step-num">3</div><div class="step-text">The Thief card is always worth 0 — and always hidden.</div></div>\n    <div class="step-card"><div class="step-num">4</div><div class="step-text">The Police studies the other players.</div></div>\n    <div class="step-card"><div class="step-num">5</div><div class="step-text">Police chooses a suspect and confirms the accusation.</div></div>\n    <div class="step-card"><div class="step-num">6</div><div class="step-text">Correct → Police gets the reward. Wrong → the Thief gets it instead.</div></div>\n    <div class="step-card"><div class="step-num">7</div><div class="step-text">After all rounds, the highest total score wins.</div></div>\n    <button class="btn btn-secondary btn-back-home" style="margin-top:10px;">← Back</button>\n  </section>\n\n  <!-- SETTINGS -->\n  <section id="screen-settings" class="screen">\n    <div class="top-bar"><h2>Settings</h2></div>\n    <div class="panel">\n      <div class="toggle-row"><span>🔊 Sound Effects</span><input id="toggle-sfx-2" type="checkbox" checked disabled title="Set per-game in Setup"></div>\n    </div>\n    <div class="panel">\n      <div class="toggle-row"><span>Sound Effects</span><input id="toggle-sfx" type="checkbox" checked></div>\n      <div class="toggle-row"><span>SFX Volume</span><input id="sfx-volume" type="range" min="0" max="1" step="0.05" value="0.7"></div>\n      <div class="toggle-row"><span>Background Music</span><input id="toggle-music" type="checkbox" checked></div>\n      <div class="toggle-row"><span>Music Volume</span><input id="music-volume" type="range" min="0" max="1" step="0.05" value="0.25"></div>\n      <div class="toggle-row"><span>3D Animations</span><input id="toggle-3d" type="checkbox" checked></div>\n      <div class="toggle-row"><span>Haptic Feedback</span><input id="toggle-haptics" type="checkbox" checked></div>\n    </div>\n    <button class="btn btn-secondary btn-back-home" style="margin-top:10px;">← Back</button>\n  </section>\n\n</div>\n\n<script src="js/cards.js"></script>\n<script src="js/sound.js"></script>\n<script src="js/bots.js"></script>\n<script src="js/game.js"></script>\n<script src="js/firebase-config.js"></script>\n<script type="module" src="js/online.js"></script>\n<script src="js/app.js"></script>\n</body>\n</html>\n'
NEW_STYLE_CSS = "/* ============================================================\n   CHOR POLICE — styles\n   Palette: deep navy/charcoal + warm gold, dark wood accents\n   ============================================================ */\n\n:root {\n  --bg-deep: #10151f;\n  --bg-panel: #1a2130;\n  --bg-panel-2: #212a3d;\n  --gold: #e8b74d;\n  --gold-soft: #f2cf7e;\n  --wood: #3a2418;\n  --wood-light: #5c3a24;\n  --text: #f2ede2;\n  --text-dim: #a9b0c3;\n  --green: #4caf7d;\n  --red: #d9634f;\n  --radius-lg: 22px;\n  --radius-md: 14px;\n  --font-display: 'Poppins', 'Nunito', sans-serif;\n  --font-body: 'Inter', 'DM Sans', sans-serif;\n}\n\n* { box-sizing: border-box; }\n\nhtml, body {\n  margin: 0; padding: 0; height: 100%;\n  background: radial-gradient(circle at 50% -10%, #1c2740 0%, var(--bg-deep) 55%);\n  color: var(--text);\n  font-family: var(--font-body);\n  overscroll-behavior: none;\n  -webkit-tap-highlight-color: transparent;\n}\n\n#app { max-width: 520px; margin: 0 auto; min-height: 100vh; position: relative; }\n\n.screen {\n  display: none;\n  min-height: 100vh;\n  padding: 24px 20px 100px;\n  animation: fadeIn 0.35s ease;\n}\n.screen.active { display: block; }\n\n@keyframes fadeIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: none; } }\n\nh1, h2, h3 { font-family: var(--font-display); margin: 0 0 6px; letter-spacing: 0.02em; }\n\n/* ---------- Buttons ---------- */\n.btn {\n  font-family: var(--font-display);\n  font-weight: 600;\n  border: none;\n  border-radius: 999px;\n  padding: 16px 22px;\n  font-size: 16px;\n  cursor: pointer;\n  width: 100%;\n  transition: transform 0.12s ease, box-shadow 0.12s ease, filter 0.12s ease;\n  display: flex; align-items: center; justify-content: center; gap: 10px;\n}\n.btn:active { transform: scale(0.97); }\n.btn-primary { background: linear-gradient(180deg, var(--gold-soft), var(--gold)); color: #241704; box-shadow: 0 6px 18px rgba(232, 183, 77, 0.35); }\n.btn-secondary { background: var(--bg-panel-2); color: var(--text); border: 1px solid #313d55; }\n.btn-ghost { background: transparent; color: var(--text-dim); font-weight: 500; }\n.btn-danger { background: linear-gradient(180deg, #e07a68, var(--red)); color: #fff; }\n.btn-lg { padding: 20px; font-size: 18px; }\n.btn:disabled { opacity: 0.4; cursor: not-allowed; }\n.btn-row { display: flex; gap: 12px; }\n\n/* ---------- Home ---------- */\n.home-hero { text-align: center; padding: 40px 0 20px; }\n.home-title {\n  font-size: 44px; font-weight: 800; font-family: var(--font-display);\n  color: var(--gold-soft); text-shadow: 0 2px 18px rgba(232,183,77,0.35);\n  margin-bottom: 4px;\n}\n.home-subtitle { color: var(--text-dim); font-size: 15px; margin-bottom: 30px; }\n.home-icon-cluster { font-size: 46px; margin-bottom: 10px; }\n.home-buttons { display: flex; flex-direction: column; gap: 14px; margin-top: 20px; }\n.home-buttons .btn small { display: block; font-weight: 400; opacity: 0.75; font-size: 12px; }\n.home-footer-links { display: flex; justify-content: center; gap: 24px; margin-top: 30px; }\n.home-footer-links a { color: var(--text-dim); text-decoration: none; font-size: 13px; }\n\n/* ---------- Panels / Cards (UI, not game cards) ---------- */\n.panel {\n  background: var(--bg-panel);\n  border: 1px solid #2a3450;\n  border-radius: var(--radius-lg);\n  padding: 18px;\n  margin-bottom: 16px;\n}\n.panel-title { font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--gold-soft); margin-bottom: 12px; }\n\n/* ---------- Stepper ---------- */\n.stepper { display: flex; align-items: center; justify-content: space-between; background: var(--bg-panel-2); border-radius: var(--radius-md); padding: 10px 14px; }\n.stepper button { width: 40px; height: 40px; border-radius: 50%; border: none; background: var(--bg-deep); color: var(--gold-soft); font-size: 20px; cursor: pointer; }\n.stepper .stepper-value { font-size: 22px; font-weight: 700; font-family: var(--font-display); }\n\n/* ---------- Card editor rows ---------- */\n.card-row { display: grid; grid-template-columns: 32px 1fr 70px auto auto; gap: 8px; align-items: center; padding: 8px 0; border-bottom: 1px solid #253048; }\n.card-row-icon { font-size: 20px; text-align: center; }\n.card-row input[type=text], .card-row input[type=number] {\n  background: var(--bg-deep); border: 1px solid #2a3450; border-radius: 8px; color: var(--text); padding: 8px; font-size: 13px; width: 100%;\n}\n.card-row-reveal, .card-row-reveal-fixed { font-size: 11px; color: var(--text-dim); white-space: nowrap; }\n.card-row-remove { background: none; border: none; color: var(--red); font-size: 16px; cursor: pointer; }\n.add-card-form { display: grid; grid-template-columns: 1fr 70px 60px; gap: 8px; margin-top: 12px; }\n.add-card-form input { background: var(--bg-deep); border: 1px solid #2a3450; border-radius: 8px; color: var(--text); padding: 10px; font-size: 13px; width: 100%; }\n\n.toggle-row { display: flex; justify-content: space-between; align-items: center; padding: 10px 0; border-bottom: 1px solid #253048; }\n.toggle-row:last-child { border-bottom: none; }\ninput[type=checkbox] { width: 20px; height: 20px; accent-color: var(--gold); }\ninput[type=range] { width: 120px; accent-color: var(--gold); }\n\n/* ---------- Lobby ---------- */\n.room-code-display { text-align: center; padding: 20px 0; }\n.room-code-display .code { font-size: 40px; font-weight: 800; letter-spacing: 0.12em; color: var(--gold-soft); font-family: var(--font-display); }\n.lobby-player { padding: 10px 14px; background: var(--bg-panel-2); border-radius: var(--radius-md); margin-bottom: 8px; }\n\n/* ---------- Game screen / persistent circular table ---------- */\n.round-banner { text-align: center; color: var(--gold-soft); font-family: var(--font-display); font-weight: 700; letter-spacing: 0.08em; margin-bottom: 14px; font-size: 14px; }\n.stage { display: none; }\n.stage.active { display: block; animation: fadeIn 0.3s ease; }\n\n.table-arena { width: 100%; max-width: 460px; margin: 0 auto; }\n.table-felt {\n  position: relative;\n  width: 100%;\n  aspect-ratio: 1 / 1;\n  border-radius: 50%;\n  background: radial-gradient(circle at 50% 36%, #234a36, #14301f 55%, #0c1e14 100%);\n  border: 10px solid var(--wood);\n  box-shadow:\n    inset 0 0 0 3px rgba(232,183,77,0.25),\n    inset 0 10px 40px rgba(0,0,0,0.55),\n    0 14px 34px rgba(0,0,0,0.5);\n}\n.table-felt-inner {\n  position: absolute; inset: 15%;\n  border-radius: 50%;\n  border: 1px dashed rgba(232,183,77,0.25);\n  pointer-events: none;\n}\n.seats-ring { position: absolute; inset: 0; }\n\n.table-center {\n  position: absolute; top: 50%; left: 50%; transform: translate(-50%,-50%);\n  display: flex; flex-direction: column; align-items: center; gap: 10px;\n  width: 62%; text-align: center; z-index: 3;\n}\n.center-deck { position: relative; width: 54px; height: 76px; margin: 0 auto; display: none; }\n.table-center.shuffling .center-deck { display: block; }\n.center-deck .deck-card {\n  position: absolute; inset: 0; border-radius: 9px;\n  background: linear-gradient(160deg, #2b3654, #171e30);\n  border: 2px solid var(--gold);\n  box-shadow: 0 6px 14px rgba(0,0,0,0.5);\n  animation: shuffleMove 1.4s ease-in-out infinite;\n}\n.center-deck .deck-card:nth-child(1) { animation-delay: 0s; }\n.center-deck .deck-card:nth-child(2) { animation-delay: 0.15s; }\n.center-deck .deck-card:nth-child(3) { animation-delay: 0.3s; }\n@keyframes shuffleMove {\n  0% { transform: translate(0,0) rotate(0deg); }\n  25% { transform: translate(-10px, -4px) rotate(-8deg); }\n  50% { transform: translate(8px, 3px) rotate(6deg); }\n  75% { transform: translate(-4px, 6px) rotate(-3deg); }\n  100% { transform: translate(0,0) rotate(0deg); }\n}\n.center-plaque {\n  background: rgba(16,21,31,0.88);\n  border: 1px solid var(--gold);\n  border-radius: 14px;\n  padding: 10px 14px;\n  font-family: var(--font-display); font-weight: 700; font-size: 12.5px;\n  color: var(--text); letter-spacing: 0.02em; line-height: 1.4;\n  box-shadow: 0 6px 18px rgba(0,0,0,0.45);\n}\n.center-plaque:empty { display: none; }\n.center-plaque .plaque-sub { display: block; font-weight: 400; font-size: 10.5px; color: var(--text-dim); margin-top: 4px; }\n.center-plaque.result-correct { border-color: var(--green); color: var(--green); }\n.center-plaque.result-wrong { border-color: var(--red); color: var(--red); }\n\n/* ---------- Seats ---------- */\n.seat {\n  position: absolute; top: 0; left: 0;\n  transform: translate(-50%, -50%);\n  display: flex; flex-direction: column; align-items: center; gap: 4px;\n  z-index: 2;\n}\n.seat-card-wrap {\n  position: relative;\n  transition: transform 0.65s cubic-bezier(0.2,0.75,0.25,1), opacity 0.35s ease;\n  transform: translate(0,0) scale(1); opacity: 1;\n}\n.seat.pre-deal .seat-card-wrap {\n  transform: translate(var(--dx,0px), var(--dy,0px)) scale(0.4) rotate(8deg);\n  opacity: 0;\n}\n\n.game-card { width: 44px; height: 64px; border-radius: 8px; perspective: 600px; position: relative; }\n.game-card-inner {\n  position: relative; width: 100%; height: 100%;\n  border-radius: 8px; transform-style: preserve-3d;\n  transition: transform 0.5s cubic-bezier(0.2,0.7,0.3,1);\n  box-shadow: 0 4px 10px rgba(0,0,0,0.45);\n}\n.game-card.flip-in .game-card-inner { transform: rotateY(180deg); }\n.card-back-side, .card-front-side {\n  position: absolute; inset: 0; border-radius: 8px;\n  backface-visibility: hidden; display: flex; align-items: center; justify-content: center;\n}\n.card-back-side {\n  background: repeating-linear-gradient(135deg, #26314c 0 6px, #1c2337 6px 12px);\n  border: 2px solid var(--gold);\n}\n.card-back-side .card-back-emblem { font-size: 17px; opacity: 0.75; }\n.card-front-side {\n  transform: rotateY(180deg);\n  flex-direction: column; gap: 1px; padding: 3px; text-align: center;\n  border: 2px solid rgba(255,255,255,0.25); color: #fff;\n}\n.card-front-side .cf-icon { font-size: 15px; line-height: 1; }\n.card-front-side .cf-name { font-size: 6px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.03em; opacity: 0.92; }\n.card-front-side .cf-value { font-size: 8.5px; font-weight: 800; }\n\n/* card face palettes — police/thief fixed, normal cards cycle a premium set */\n.cf-police { background: radial-gradient(circle at 50% 20%, #2f5f92, #12253c 85%); border-color: #6fa8dc; }\n.cf-thief  { background: radial-gradient(circle at 50% 20%, #7a2f2f, #2c1010 85%); border-color: #d98a8a; }\n.cf-pal-0 { background: radial-gradient(circle at 50% 20%, #a5822e, #3a2a08 85%); border-color: var(--gold); }\n.cf-pal-1 { background: radial-gradient(circle at 50% 20%, #47506b, #1b2030 85%); border-color: #8b94b8; }\n.cf-pal-2 { background: radial-gradient(circle at 50% 20%, #2c5a78, #0f2330 85%); border-color: #7fc4e8; }\n.cf-pal-3 { background: radial-gradient(circle at 50% 20%, #7a5a2c, #2c1e0c 85%); border-color: #d9b877; }\n.cf-pal-4 { background: radial-gradient(circle at 50% 20%, #6b3378, #24102c 85%); border-color: #cf95dd; }\n.cf-pal-5 { background: radial-gradient(circle at 50% 20%, #326b4f, #0f261b 85%); border-color: #85d9ac; }\n\n.seat-tag {\n  display: flex; align-items: center; gap: 5px;\n  background: rgba(16,21,31,0.85); border: 1px solid #2a3450; border-radius: 999px;\n  padding: 3px 9px 3px 3px; max-width: 116px;\n}\n.seat-avatar {\n  width: 21px; height: 21px; border-radius: 50%; background: var(--bg-panel-2);\n  display: flex; align-items: center; justify-content: center; font-size: 12px; flex-shrink: 0;\n}\n.seat-info { display: flex; flex-direction: column; line-height: 1.1; min-width: 0; }\n.seat-name { font-size: 9.5px; font-weight: 700; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 80px; }\n.seat-score { font-size: 9px; color: var(--gold-soft); font-weight: 700; }\n\n.seat.is-police .seat-tag { border-color: var(--gold); box-shadow: 0 0 0 2px rgba(232,183,77,0.25); }\n.seat.is-police .game-card-inner { box-shadow: 0 0 0 2px var(--gold), 0 4px 14px rgba(232,183,77,0.5); }\n.seat.is-thief-reveal .seat-tag { border-color: var(--red); box-shadow: 0 0 0 2px rgba(217,99,79,0.3); }\n.seat.is-thief-reveal .game-card-inner { box-shadow: 0 0 0 2px var(--red), 0 4px 14px rgba(217,99,79,0.5); }\n\n.seat.clickable { cursor: pointer; }\n.seat.clickable .seat-card-wrap { animation: seatPulse 1.6s ease-in-out infinite; }\n@keyframes seatPulse { 0%, 100% { filter: brightness(1); } 50% { filter: brightness(1.3); } }\n.seat.selected .seat-tag { border-color: var(--gold); background: rgba(232,183,77,0.18); }\n\n.score-float {\n  position: absolute; top: -14px; left: 50%; transform: translateX(-50%);\n  font-family: var(--font-display); font-weight: 800; font-size: 12px; color: var(--gold-soft);\n  animation: scoreFloat 1.4s ease forwards; pointer-events: none; white-space: nowrap; z-index: 4;\n}\n@keyframes scoreFloat {\n  0% { opacity: 0; transform: translate(-50%, 0); }\n  20% { opacity: 1; }\n  100% { opacity: 0; transform: translate(-50%, -26px); }\n}\n\n/* ---------- Round results sheet (slides over the table) ---------- */\n.round-sheet {\n  display: none; position: fixed; inset: 0; background: rgba(10,14,22,0.7);\n  align-items: flex-end; justify-content: center; z-index: 55;\n}\n.round-sheet.active { display: flex; }\n.round-sheet-inner {\n  background: var(--bg-panel); width: 100%; max-width: 520px; border-radius: 24px 24px 0 0;\n  padding: 22px 20px 30px; animation: sheetUp 0.3s ease; border-top: 1px solid var(--gold);\n}\n\n/* ---------- Guess confirm modal ---------- */\n.guess-confirm-modal {\n  display: none; position: fixed; inset: 0; background: rgba(10,14,22,0.7);\n  align-items: flex-end; justify-content: center; z-index: 60;\n}\n.guess-confirm-modal.active { display: flex; }\n.guess-confirm-sheet {\n  background: var(--bg-panel); width: 100%; max-width: 520px; border-radius: 24px 24px 0 0;\n  padding: 26px 20px 34px; text-align: center; animation: sheetUp 0.25s ease;\n}\n@keyframes sheetUp { from { transform: translateY(30px); opacity: 0; } to { transform: none; opacity: 1; } }\n\n.score-row { display: grid; grid-template-columns: 1fr auto 50px; gap: 10px; padding: 12px 6px; border-bottom: 1px solid #253048; align-items: center; }\n.score-delta { color: var(--gold-soft); font-weight: 700; }\n.score-total { text-align: right; font-weight: 800; }\n\n.final-winner { text-align: center; font-size: 24px; font-family: var(--font-display); color: var(--gold-soft); margin: 10px 0 24px; }\n.final-row { display: flex; justify-content: space-between; padding: 14px; border-radius: var(--radius-md); margin-bottom: 8px; background: var(--bg-panel-2); font-weight: 600; }\n.final-row.winner { background: linear-gradient(90deg, rgba(232,183,77,0.2), transparent); border: 1px solid var(--gold); }\n\n/* ---------- Player chips / mute ---------- */\n.player-chip { display: flex; flex-direction: column; align-items: center; font-size: 11px; color: var(--text-dim); }\n.player-avatar { font-size: 22px; }\n\n/* ---------- How to play ---------- */\n.step-card { display: flex; gap: 14px; align-items: flex-start; margin-bottom: 16px; }\n.step-num { background: var(--gold); color: #241704; font-weight: 800; border-radius: 50%; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; font-family: var(--font-display); }\n.step-text { color: var(--text-dim); font-size: 14px; line-height: 1.5; }\n\n/* ---------- Misc ---------- */\n.top-bar { display: flex; align-items: center; justify-content: space-between; margin-bottom: 16px; }\n.top-bar h2 { margin: 0; }\n.small-note { font-size: 12px; color: var(--text-dim); margin-top: 6px; }\n\n@media (min-width: 540px) {\n  .home-title { font-size: 52px; }\n}\n"
NEW_APP_JS = '// ============================================================\n// APP.JS — Screen routing + orchestration for both game modes\n// ============================================================\n\nconst App = {\n  mode: null, // \'offline\' | \'online\'\n  cardDefs: null,\n  playerName: \'You\',\n  numPlayers: 4,\n  numRounds: 5,\n  policeRewardPoints: 100,\n  botDifficulty: \'normal\',\n  game: null, // ChorPoliceGame instance (offline)\n  humanId: \'human_1\',\n  // online-specific\n  roomCode: null,\n  myCard: null,\n  unsubRoom: null,\n  unsubCard: null,\n  latestRoom: null,\n  settings: { sfxOn: true, musicOn: true, animOn: true, haptics: true },\n};\n\nfunction $(sel) { return document.querySelector(sel); }\nfunction $all(sel) { return Array.from(document.querySelectorAll(sel)); }\n\nfunction showScreen(id) {\n  $all(\'.screen\').forEach(s => s.classList.remove(\'active\'));\n  $(`#${id}`).classList.add(\'active\');\n}\n\nfunction haptic(ms = 15) {\n  if (App.settings.haptics && navigator.vibrate) navigator.vibrate(ms);\n}\n\nfunction bindClick(id, fn) {\n  const el = document.getElementById(id);\n  if (el) el.addEventListener(\'click\', (...args) => { CP_Sound.buttonClick(); haptic(); fn(...args); });\n}\n\n// ---------------------------------------------------------------\n// INIT\n// ---------------------------------------------------------------\ndocument.addEventListener(\'DOMContentLoaded\', () => {\n  App.cardDefs = CP_Cards.defaultCardSet();\n  renderCardEditor();\n  wireHome();\n  wireSetup();\n  wireGameScreen();\n  wireSettings();\n  wireOnlineScreens();\n  showScreen(\'screen-home\');\n});\n\n// ---------------------------------------------------------------\n// HOME / MODE SELECT / HOW TO PLAY / SETTINGS\n// ---------------------------------------------------------------\nfunction wireHome() {\n  bindClick(\'btn-play-offline\', () => { App.mode = \'offline\'; showScreen(\'screen-setup\'); $(\'#setup-online-only\').style.display = \'none\'; $(\'#setup-title\').textContent = \'Play vs Bots\'; });\n  bindClick(\'btn-play-online\', () => { showScreen(\'screen-online-choice\'); });\n  bindClick(\'btn-how-to-play\', () => showScreen(\'screen-how-to-play\'));\n  bindClick(\'btn-settings\', () => showScreen(\'screen-settings\'));\n  $all(\'.btn-back-home\').forEach(b => b.addEventListener(\'click\', () => { CP_Sound.buttonClick(); showScreen(\'screen-home\'); }));\n\n  bindClick(\'btn-online-create\', () => { App.mode = \'online\'; showScreen(\'screen-setup\'); $(\'#setup-online-only\').style.display = \'block\'; $(\'#setup-title\').textContent = \'Create Room\'; });\n  bindClick(\'btn-online-join\', () => showScreen(\'screen-join\'));\n  bindClick(\'btn-join-submit\', async () => {\n    const code = $(\'#join-room-code\').value.trim().toUpperCase();\n    const name = $(\'#join-player-name\').value.trim() || \'Player\';\n    if (code.length < 4) return alert(\'Enter a valid room code.\');\n    try {\n      await ensureFirebaseReady();\n      App.playerName = name;\n      App.roomCode = code;\n      await CP_Online.joinRoom(code, name);\n      enterOnlineLobby(code);\n    } catch (e) { alert(e.message); }\n  });\n}\n\n// ---------------------------------------------------------------\n// CARD EDITOR (shared by offline + online setup)\n// ---------------------------------------------------------------\nfunction renderCardEditor() {\n  const list = $(\'#card-list\');\n  list.innerHTML = \'\';\n  App.cardDefs.forEach(card => {\n    const row = document.createElement(\'div\');\n    row.className = \'card-row\';\n    const locked = card.locked;\n    row.innerHTML = `\n      <span class="card-row-icon">${card.icon}</span>\n      <input class="card-row-name" type="text" value="${card.name}" ${locked ? \'disabled\' : \'\'} data-id="${card.id}" data-field="name">\n      <input class="card-row-value" type="${card.type === \'police\' ? \'text\' : \'number\'}" value="${card.value}" ${card.type !== \'normal\' ? \'disabled\' : \'\'} data-id="${card.id}" data-field="value">\n      ${card.type === \'normal\' ? `<label class="card-row-reveal"><input type="checkbox" ${card.revealed ? \'checked\' : \'\'} data-id="${card.id}" data-field="revealed"> Show</label>` : `<span class="card-row-reveal-fixed">${card.type === \'police\' ? \'Always shown\' : \'Hidden\'}</span>`}\n      ${locked ? \'\' : `<button class="card-row-remove" data-id="${card.id}">✕</button>`}\n    `;\n    list.appendChild(row);\n  });\n\n  list.querySelectorAll(\'input\').forEach(inp => {\n    inp.addEventListener(\'change\', e => {\n      const { id, field } = e.target.dataset;\n      const card = App.cardDefs.find(c => c.id === id);\n      if (field === \'revealed\') card.revealed = e.target.checked;\n      else if (field === \'value\') card.value = Number(e.target.value);\n      else card.name = e.target.value;\n    });\n  });\n  list.querySelectorAll(\'.card-row-remove\').forEach(btn => {\n    btn.addEventListener(\'click\', () => {\n      App.cardDefs = App.cardDefs.filter(c => c.id !== btn.dataset.id);\n      renderCardEditor();\n    });\n  });\n}\n\nfunction wireSetup() {\n  bindClick(\'btn-add-card\', () => {\n    const name = $(\'#new-card-name\').value.trim();\n    const value = Number($(\'#new-card-value\').value);\n    const icon = $(\'#new-card-icon\').value.trim() || \'🎴\';\n    if (!name || Number.isNaN(value)) return alert(\'Enter a card name and numeric value.\');\n    App.cardDefs.push({ id: CP_Cards.makeId(\'card\'), name, value, icon, type: \'normal\', revealed: false });\n    $(\'#new-card-name\').value = \'\'; $(\'#new-card-value\').value = \'\'; $(\'#new-card-icon\').value = \'\';\n    renderCardEditor();\n  });\n\n  bindClick(\'btn-players-minus\', () => setPlayerCount(App.numPlayers - 1));\n  bindClick(\'btn-players-plus\', () => setPlayerCount(App.numPlayers + 1));\n  bindClick(\'btn-rounds-minus\', () => setRoundCount(App.numRounds - 1));\n  bindClick(\'btn-rounds-plus\', () => setRoundCount(App.numRounds + 1));\n\n  bindClick(\'btn-setup-continue\', () => {\n    App.numRounds = Number($(\'#rounds-count\').textContent);\n    App.policeRewardPoints = Number($(\'#police-reward\').value) || 100;\n    App.botDifficulty = $(\'#bot-difficulty\').value;\n    App.settings.animOn = $(\'#toggle-3d\').checked;\n    App.settings.sfxOn = $(\'#toggle-sfx\').checked;\n    App.settings.musicOn = $(\'#toggle-music\').checked;\n    CP_Sound.setSfxOn(App.settings.sfxOn);\n    CP_Sound.setMusicOn(App.settings.musicOn);\n\n    if (App.cardDefs.length < 3) return alert(\'Add at least one custom card besides Police & Thief.\');\n\n    if (App.mode === \'offline\') startOfflineGame();\n    else createOnlineRoomFlow();\n  });\n\n  setPlayerCount(4);\n  setRoundCount(5);\n}\n\nfunction setPlayerCount(n) {\n  App.numPlayers = Math.max(4, Math.min(10, n));\n  $(\'#players-count\').textContent = App.numPlayers;\n}\nfunction setRoundCount(n) {\n  App.numRounds = Math.max(1, Math.min(20, n));\n  $(\'#rounds-count\').textContent = App.numRounds;\n}\n\n// ---------------------------------------------------------------\n// OFFLINE MODE\n// ---------------------------------------------------------------\nfunction startOfflineGame() {\n  const botNames = CP_Bots.pickBotNames(App.numPlayers - 1);\n  const players = [\n    { id: App.humanId, name: App.playerName || \'You\', avatar: \'🧑\', isHost: true, isBot: false },\n    ...botNames.map((name, i) => ({ id: `bot_${i}`, name, avatar: \'🤖\', isHost: false, isBot: true, botDifficulty: App.botDifficulty })),\n  ];\n  App.game = new CP_Game.ChorPoliceGame({\n    players, cardDefs: App.cardDefs, numRounds: App.numRounds, policeRewardPoints: App.policeRewardPoints,\n  });\n  showScreen(\'screen-game\');\n  CP_Sound.startMusic();\n  App.game.startRound();\n  runOfflineRoundSequence();\n}\n\nasync function runOfflineRoundSequence() {\n  const game = App.game;\n  showStage(\'stage-table\');\n  renderRoundBanner(game);\n  clearSeatRoles();\n  hideRoundSheet();\n\n  await playShuffleAndDeal(game.players, App.humanId, game.assignment[App.humanId], App.settings.animOn);\n\n  game.advanceToDealing();\n  game.advanceToPublicReveal();\n  const { revealedCardsByPlayer } = game.publicRevealState();\n  revealCardsAtSeats(revealedCardsByPlayer, App.humanId);\n  await wait(App.settings.animOn ? 900 : 200);\n\n  game.advanceToPoliceIdentified();\n  CP_Sound.policeIdentified();\n  const police = game.players.find(p => p.id === game.policeId);\n  markSeatRole(game.policeId, \'is-police\');\n  setCenterPlaque(police.id === App.humanId\n    ? \'🕵️ YOU ARE THE POLICE\'\n    : `🕵️ ${escapeHtml(police.name).toUpperCase()} IS THE POLICE`);\n  await wait(1400);\n\n  game.advanceToPoliceGuess();\n  if (game.policeId === App.humanId) {\n    setCenterPlaque(\'WHO IS THE THIEF?<span class="plaque-sub">Tap a player to accuse</span>\');\n    enableSeatGuessing(game.suspects(), suspectId => submitOfflineGuess(suspectId));\n  } else {\n    setCenterPlaque(`${escapeHtml(police.name).toUpperCase()} IS DECIDING…`);\n    await wait(1200);\n    const suspects = game.suspects();\n    const publicInfo = game.publicRevealState();\n    const bot = game.players.find(p => p.id === game.policeId);\n    const suspectId = CP_Bots.botChooseSuspect(bot.id, suspects, publicInfo, bot.botDifficulty || \'normal\');\n    submitOfflineGuess(suspectId);\n  }\n}\n\nfunction submitOfflineGuess(suspectId) {\n  const game = App.game;\n  disableSeatGuessing();\n  game.submitGuess(suspectId);\n\n  const thief = game.players.find(p => p.id === game.thiefId);\n  const police = game.players.find(p => p.id === game.policeId);\n  markSeatRole(thief.id, \'is-thief-reveal\');\n  revealCardsAtSeats({ [thief.id]: game.assignment[thief.id] }, App.humanId);\n\n  if (game.correctGuessResult) {\n    setCenterPlaque(`🎉 THIEF CAUGHT!<span class="plaque-sub">${escapeHtml(thief.name)} was the Thief. ${escapeHtml(police.name)} +${game.policeRewardPoints}</span>`, \'result-correct\');\n    CP_Sound.correctGuess();\n  } else {\n    setCenterPlaque(`💨 THE THIEF ESCAPED!<span class="plaque-sub">${escapeHtml(thief.name)} was the Thief. ${escapeHtml(thief.name)} +${game.policeRewardPoints}</span>`, \'result-wrong\');\n    CP_Sound.wrongGuess();\n  }\n\n  game.players.forEach(p => { floatScore(p.id, p.roundScore); setSeatScore(p.id, p.score); });\n\n  setTimeout(() => {\n    game.advanceToRoundEnd();\n    const entry = game.roundHistory[game.roundHistory.length - 1];\n    showRoundSheet(`ROUND ${entry.round} RESULTS`, entry.scores);\n    CP_Sound.roundComplete();\n\n    setTimeout(() => {\n      hideRoundSheet();\n      if (game.hasNextRound()) {\n        game.advanceToNextRoundOrFinal();\n        runOfflineRoundSequence();\n      } else {\n        game.state = \'FINAL_RESULT\';\n        showFinalResults(game.leaderboard(), game.winner());\n      }\n    }, 2600);\n  }, 1600);\n}\n\nfunction wait(ms) { return new Promise(r => setTimeout(r, ms)); }\n\n// ---------------------------------------------------------------\n// GAME TABLE RENDERING — persistent circular table shared by both\n// offline (bots) and online (Firebase-synced) modes.\n// ---------------------------------------------------------------\nfunction showStage(id) {\n  $all(\'.stage\').forEach(s => s.classList.remove(\'active\'));\n  $(`#${id}`).classList.add(\'active\');\n}\n\nfunction renderRoundBanner(game) {\n  $(\'#round-banner\').textContent = `ROUND ${game.round} / ${game.numRounds}`;\n}\n\nfunction escapeHtml(s) { const d = document.createElement(\'div\'); d.textContent = s; return d.innerHTML; }\n\n// Deterministic premium color palette per card so custom host-defined\n// cards still look distinct and consistent round to round.\nfunction cardPaletteClass(card) {\n  if (card.type === \'police\') return \'cf-police\';\n  if (card.type === \'thief\') return \'cf-thief\';\n  const key = String(card.sourceId || card.name || card.id || \'\');\n  let h = 0;\n  for (let i = 0; i < key.length; i++) h = (h * 31 + key.charCodeAt(i)) >>> 0;\n  return `cf-pal-${h % 6}`;\n}\n\nfunction gameCardHtml(pid) {\n  return `<div class="seat-card-wrap">\n    <div class="game-card" data-pid="${pid}">\n      <div class="game-card-inner">\n        <div class="card-back-side"><span class="card-back-emblem">🂠</span></div>\n        <div class="card-front-side"></div>\n      </div>\n    </div>\n  </div>`;\n}\n\nfunction seatHtml(p, isYou) {\n  return `<div class="seat" data-pid="${p.id}" id="seat-${p.id}">\n    ${gameCardHtml(p.id)}\n    <div class="seat-tag">\n      <div class="seat-avatar">${p.avatar || \'🧑\'}</div>\n      <div class="seat-info">\n        <div class="seat-name">${escapeHtml(p.name)}${isYou ? \' (You)\' : \'\'}</div>\n        <div class="seat-score" id="seat-score-${p.id}">${p.score ?? 0}</div>\n      </div>\n    </div>\n  </div>`;\n}\n\nfunction renderTableSeats(players, meId) {\n  const ring = $(\'#seats-ring\');\n  ring.innerHTML = players.map(p => seatHtml(p, p.id === meId)).join(\'\');\n  positionSeats();\n}\n\n// Places each seat around the table\'s perimeter based on player count,\n// and records the vector back to the table center (--dx/--dy) so cards\n// can animate outward from the deck when dealt.\nfunction positionSeats() {\n  const felt = document.querySelector(\'.table-felt\');\n  const ring = $(\'#seats-ring\');\n  if (!felt || !ring) return;\n  const seats = $all(\'#seats-ring .seat\');\n  if (!seats.length) return;\n  const w = felt.clientWidth, h = felt.clientHeight;\n  if (!w || !h) return;\n  const cx = w / 2, cy = h / 2;\n  const radius = Math.min(w, h) / 2 - 40;\n  seats.forEach((seat, i) => {\n    const angle = (i / seats.length) * Math.PI * 2 - Math.PI / 2;\n    const x = cx + radius * Math.cos(angle);\n    const y = cy + radius * Math.sin(angle);\n    seat.style.left = `${x}px`;\n    seat.style.top = `${y}px`;\n    seat.style.setProperty(\'--dx\', `${cx - x}px`);\n    seat.style.setProperty(\'--dy\', `${cy - y}px`);\n  });\n}\nwindow.addEventListener(\'resize\', positionSeats);\n\nfunction setCardFace(pid, card) {\n  const cardEl = document.querySelector(`#seats-ring .seat[data-pid="${pid}"] .game-card`);\n  if (!cardEl) return;\n  const front = cardEl.querySelector(\'.card-front-side\');\n  front.className = `card-front-side ${cardPaletteClass(card)}`;\n  front.innerHTML = `<div class="cf-icon">${card.icon}</div><div class="cf-name">${escapeHtml(card.name)}</div><div class="cf-value">${card.value}</div>`;\n  cardEl.classList.add(\'flip-in\');\n}\n\n// Rebuilds the seat ring, shows the shuffling deck at the table center,\n// then deals every card outward to its seat with a staggered animation.\nasync function playShuffleAndDeal(players, meId, myCard, animOn) {\n  const tc = $(\'#table-center\');\n  tc.classList.add(\'shuffling\');\n  setCenterPlaque(\'\');\n  CP_Sound.cardShuffle();\n\n  renderTableSeats(players, meId);\n  $all(\'#seats-ring .seat\').forEach(s => s.classList.add(\'pre-deal\'));\n  await wait(animOn ? 1300 : 200);\n\n  tc.classList.remove(\'shuffling\');\n  CP_Sound.cardDeal();\n  const seats = $all(\'#seats-ring .seat\');\n  const stagger = animOn ? 110 : 20;\n  seats.forEach((seat, i) => setTimeout(() => seat.classList.remove(\'pre-deal\'), i * stagger));\n  await wait(seats.length * stagger + (animOn ? 550 : 150));\n\n  if (meId && myCard) setCardFace(meId, myCard);\n}\n\nfunction revealCardsAtSeats(revealMap, exceptId) {\n  Object.entries(revealMap || {}).forEach(([pid, card]) => {\n    if (!card || pid === exceptId) return;\n    const cardEl = document.querySelector(`#seats-ring .seat[data-pid="${pid}"] .game-card`);\n    if (!cardEl || cardEl.classList.contains(\'flip-in\')) return;\n    setCardFace(pid, card);\n    CP_Sound.cardFlip();\n  });\n}\n\nfunction setCenterPlaque(html, cls = \'\') {\n  const el = $(\'#center-plaque\');\n  el.innerHTML = html;\n  el.className = `center-plaque ${cls}`.trim();\n}\n\nfunction clearSeatRoles() {\n  $all(\'#seats-ring .seat\').forEach(s => s.classList.remove(\'is-police\', \'is-thief-reveal\', \'clickable\', \'selected\'));\n}\n\nfunction markSeatRole(pid, cls) {\n  const seat = document.querySelector(`#seats-ring .seat[data-pid="${pid}"]`);\n  if (seat) seat.classList.add(cls);\n}\n\nfunction enableSeatGuessing(suspects, onPick) {\n  suspects.forEach(pid => {\n    const seat = document.querySelector(`#seats-ring .seat[data-pid="${pid}"]`);\n    if (!seat) return;\n    seat.classList.add(\'clickable\');\n    seat.onclick = () => {\n      CP_Sound.selecting(); haptic();\n      $all(\'#seats-ring .seat\').forEach(s => s.classList.remove(\'selected\'));\n      seat.classList.add(\'selected\');\n      $(\'#confirm-suspect-name\').textContent = seat.querySelector(\'.seat-name\').textContent;\n      $(\'#guess-confirm\').classList.add(\'active\');\n      $(\'#btn-catch-him\').onclick = () => { $(\'#guess-confirm\').classList.remove(\'active\'); onPick(pid); };\n      $(\'#btn-cancel-guess\').onclick = () => { $(\'#guess-confirm\').classList.remove(\'active\'); seat.classList.remove(\'selected\'); };\n    };\n  });\n}\n\nfunction disableSeatGuessing() {\n  $all(\'#seats-ring .seat.clickable\').forEach(s => { s.classList.remove(\'clickable\'); s.onclick = null; });\n}\n\nfunction floatScore(pid, delta) {\n  if (!delta) return;\n  const seat = document.querySelector(`#seats-ring .seat[data-pid="${pid}"]`);\n  if (!seat) return;\n  const el = document.createElement(\'div\');\n  el.className = \'score-float\';\n  el.textContent = `+${delta}`;\n  seat.appendChild(el);\n  setTimeout(() => el.remove(), 1450);\n}\n\nfunction setSeatScore(pid, total) {\n  const el = document.getElementById(`seat-score-${pid}`);\n  if (el) el.textContent = total;\n}\n\nfunction showRoundSheet(title, scores) {\n  $(\'#scoreboard-title\').textContent = title;\n  $(\'#scoreboard-list\').innerHTML = scores.slice().sort((a, b) => b.total - a.total)\n    .map(s => `<div class="score-row"><span>${escapeHtml(s.name)}</span><span class="score-delta">+${s.roundScore}</span><span class="score-total">${s.total}</span></div>`).join(\'\');\n  $(\'#round-sheet\').classList.add(\'active\');\n}\n\nfunction hideRoundSheet() { $(\'#round-sheet\').classList.remove(\'active\'); }\n\nfunction showFinalResults(leaderboard, winner) {\n  showStage(\'stage-final\');\n  CP_Sound.victory();\n  $(\'#final-winner\').textContent = `🏆 ${winner.name.toUpperCase()} WINS!`;\n  $(\'#final-list\').innerHTML = leaderboard.map((p, i) => {\n    const medal = [\'🥇\', \'🥈\', \'🥉\'][i] || `${i + 1}.`;\n    return `<div class="final-row ${i === 0 ? \'winner\' : \'\'}"><span>${medal} ${escapeHtml(p.name)}</span><span>${p.score}</span></div>`;\n  }).join(\'\');\n}\n\nfunction wireGameScreen() {\n  bindClick(\'btn-play-again\', () => {\n    if (App.mode === \'offline\') startOfflineGame();\n    else showScreen(\'screen-home\');\n  });\n  bindClick(\'btn-final-home\', () => { CP_Sound.stopMusic(); showScreen(\'screen-home\'); });\n}\n\nfunction wireSettings() {\n  const s = App.settings;\n  $(\'#toggle-sfx\').checked = s.sfxOn;\n  $(\'#toggle-music\').checked = s.musicOn;\n  $(\'#toggle-3d\').checked = s.animOn;\n  $(\'#toggle-haptics\').checked = s.haptics;\n  $(\'#toggle-sfx\').addEventListener(\'change\', e => { s.sfxOn = e.target.checked; CP_Sound.setSfxOn(s.sfxOn); });\n  $(\'#toggle-music\').addEventListener(\'change\', e => { s.musicOn = e.target.checked; CP_Sound.setMusicOn(s.musicOn); });\n  $(\'#toggle-3d\').addEventListener(\'change\', e => { s.animOn = e.target.checked; });\n  $(\'#toggle-haptics\').addEventListener(\'change\', e => { s.haptics = e.target.checked; });\n  $(\'#sfx-volume\').addEventListener(\'input\', e => CP_Sound.setSfxVolume(Number(e.target.value)));\n  $(\'#music-volume\').addEventListener(\'input\', e => CP_Sound.setMusicVolume(Number(e.target.value)));\n}\n\n// ---------------------------------------------------------------\n// ONLINE MODE\n// ---------------------------------------------------------------\nlet firebaseReady = false;\nasync function ensureFirebaseReady() {\n  if (firebaseReady) return;\n  if (!window.FIREBASE_CONFIG || !window.FIREBASE_CONFIG.apiKey) {\n    throw new Error(\'Firebase isn\\\'t configured yet — add your project keys to js/firebase-config.js.\');\n  }\n  await CP_Online.initFirebase(window.FIREBASE_CONFIG);\n  firebaseReady = true;\n}\n\nfunction wireOnlineScreens() {\n  bindClick(\'btn-lobby-start\', async () => {\n    if (!App.latestRoom || App.latestRoom.hostId !== CP_Online.uid) return;\n    await CP_Online.hostStartGame(App.roomCode);\n  });\n  bindClick(\'btn-lobby-copy\', () => {\n    navigator.clipboard?.writeText(App.roomCode);\n    $(\'#btn-lobby-copy\').textContent = \'Copied!\';\n    setTimeout(() => { $(\'#btn-lobby-copy\').textContent = \'Copy Code\'; }, 1200);\n  });\n  bindClick(\'btn-lobby-leave\', async () => {\n    await CP_Online.leaveRoom(App.roomCode);\n    cleanupOnlineListeners();\n    showScreen(\'screen-home\');\n  });\n}\n\nasync function createOnlineRoomFlow() {\n  try {\n    await ensureFirebaseReady();\n    const code = await CP_Online.createRoom(App.playerName || \'Host\', {\n      numRounds: App.numRounds, cardDefs: App.cardDefs, policeRewardPoints: App.policeRewardPoints,\n      maxPlayers: 10,\n    });\n    App.roomCode = code;\n    enterOnlineLobby(code);\n  } catch (e) { alert(e.message); }\n}\n\nfunction enterOnlineLobby(code) {\n  showScreen(\'screen-lobby\');\n  $(\'#lobby-room-code\').textContent = code;\n\n  App.unsubRoom = CP_Online.listenToRoom(code, room => {\n    App.latestRoom = room;\n    if (room.state === \'LOBBY\') renderLobby(room);\n    else if (room.state !== \'LOBBY\') driveOnlineGame(room);\n  });\n  App.unsubCard = CP_Online.listenToMyPrivateCard(code, card => { App.myCard = card; });\n}\n\nfunction renderLobby(room) {\n  const players = Object.values(room.players).filter(p => p.isConnected);\n  $(\'#lobby-players-count\').textContent = `${players.length} / ${room.maxPlayers}`;\n  $(\'#lobby-rounds\').textContent = room.numRounds;\n  $(\'#lobby-player-list\').innerHTML = players.map(p =>\n    `<div class="lobby-player">${p.isHost ? \'👑\' : \'👤\'} ${escapeHtml(p.name)}${p.id === CP_Online.uid ? \' (You)\' : \'\'}</div>`\n  ).join(\'\');\n  const isHost = room.hostId === CP_Online.uid;\n  $(\'#btn-lobby-start\').style.display = isHost ? \'block\' : \'none\';\n  $(\'#lobby-waiting-text\').style.display = isHost ? \'none\' : \'block\';\n  $(\'#btn-lobby-start\').disabled = players.length < 4;\n}\n\nlet lastRenderedState = null;\nlet lastRenderedRound = null;\nasync function driveOnlineGame(room) {\n  if (!document.getElementById(\'screen-game\').classList.contains(\'active\')) {\n    showScreen(\'screen-game\');\n    CP_Sound.startMusic();\n  }\n  showStage(\'stage-table\');\n  renderRoundBanner({ round: room.round, numRounds: room.numRounds });\n\n  const stateChanged = room.state !== lastRenderedState || room.round !== lastRenderedRound;\n  lastRenderedState = room.state; lastRenderedRound = room.round;\n  if (!stateChanged) return; // avoid re-triggering animations on unrelated field updates\n\n  const players = Object.values(room.players).filter(p => p.isConnected);\n  clearSeatRoles();\n  hideRoundSheet();\n\n  if (room.state === \'PUBLIC_REVEAL\') {\n    await playShuffleAndDeal(players, CP_Online.uid, App.myCard, App.settings.animOn);\n    revealCardsAtSeats(room.revealedCardsByPlayer || {}, CP_Online.uid);\n  }\n  if (room.state === \'RESULT\' || room.state === \'SCORE_UPDATE\' || room.state === \'FINAL_RESULT\') {\n    // Host performs the authoritative resolution once.\n    if (room.hostId === CP_Online.uid && room.state === \'RESULT\') {\n      await CP_Online.hostResolveRound(App.roomCode);\n      return; // the resulting snapshot re-triggers this function\n    }\n  }\n  if (room.state === \'RESULT\') return; // wait for host to resolve\n\n  if (room.state === \'SCORE_UPDATE\' || room.state === \'FINAL_RESULT\') {\n    const police = players.find(p => p.id === room.policeId);\n    const thief = players.find(p => p.id === room.thiefId);\n    const correct = room.result === \'CORRECT\';\n    if (police && thief) {\n      markSeatRole(thief.id, \'is-thief-reveal\');\n      setCenterPlaque(correct\n        ? `🎉 THIEF CAUGHT!<span class="plaque-sub">${escapeHtml(thief.name)} was the Thief. ${escapeHtml(police.name)} +${room.policeRewardPoints}</span>`\n        : `💨 THE THIEF ESCAPED!<span class="plaque-sub">${escapeHtml(thief.name)} was the Thief. ${escapeHtml(thief.name)} +${room.policeRewardPoints}</span>`,\n        correct ? \'result-correct\' : \'result-wrong\');\n    }\n    correct ? CP_Sound.correctGuess() : CP_Sound.wrongGuess();\n\n    const last = room.roundHistory[room.roundHistory.length - 1];\n    if (last) last.scores.forEach(s => { floatScore(s.id, s.roundScore); setSeatScore(s.id, s.total); });\n\n    setTimeout(() => {\n      if (last) showRoundSheet(`ROUND ${last.round} RESULTS`, last.scores);\n      CP_Sound.roundComplete();\n\n      if (room.state === \'FINAL_RESULT\') {\n        setTimeout(() => showFinalResults(Object.values(room.players).sort((a, b) => b.score - a.score), Object.values(room.players).sort((a, b) => b.score - a.score)[0]), 2400);\n      } else if (room.hostId === CP_Online.uid) {\n        setTimeout(() => CP_Online.hostNextRound(App.roomCode), 2600);\n      }\n    }, 1600);\n    return;\n  }\n\n  if (room.policeId === CP_Online.uid && !room.guessedSuspectId && room.state === \'PUBLIC_REVEAL\') {\n    setTimeout(() => {\n      markSeatRole(room.policeId, \'is-police\');\n      setCenterPlaque(\'WHO IS THE THIEF?<span class="plaque-sub">Tap a player to accuse</span>\');\n      const suspects = players.filter(p => p.id !== room.policeId).map(p => p.id);\n      enableSeatGuessing(suspects, async pid => { await CP_Online.submitGuess(App.roomCode, pid); });\n    }, 1800);\n  } else if (room.state === \'PUBLIC_REVEAL\') {\n    const police = players.find(p => p.id === room.policeId);\n    setTimeout(() => {\n      markSeatRole(room.policeId, \'is-police\');\n      setCenterPlaque(police ? `🕵️ ${escapeHtml(police.name).toUpperCase()} IS THE POLICE` : \'\');\n      CP_Sound.policeIdentified();\n    }, 900);\n    setTimeout(() => {\n      setCenterPlaque(police ? `${escapeHtml(police.name).toUpperCase()} IS DECIDING…` : \'\');\n    }, 2300);\n  }\n}\n\nfunction cleanupOnlineListeners() {\n  if (App.unsubRoom) App.unsubRoom();\n  if (App.unsubCard) App.unsubCard();\n  App.unsubRoom = null; App.unsubCard = null;\n}\n'

# Marker that identifies the OLD (unpatched) app.js so we know where
# the shared head (App state, home/setup wiring, card editor, offline
# game bootstrap) ends and the part we're replacing begins.
APP_JS_SPLIT_MARKER = "async function runOfflineRoundSequence() {"

# Markers used to detect "already patched" so the script is idempotent.
ALREADY_PATCHED_HTML_MARKER = 'id="stage-table"'
ALREADY_PATCHED_CSS_MARKER = ".table-felt {"
ALREADY_PATCHED_JS_MARKER = "function playShuffleAndDeal("


def patch_index_html(path: Path) -> None:
    content = path.read_text(encoding="utf-8")
    if ALREADY_PATCHED_HTML_MARKER in content:
        print(f"  - {path.name}: already patched, skipping")
        return
    if "<!-- GAME SCREEN -->" not in content or "stage-shuffle" not in content:
        raise SystemExit(
            f"ERROR: {path} doesn't look like the expected original file "
            "(couldn't find the old GAME SCREEN block). Aborting so nothing "
            "gets corrupted — please check you're pointing this script at "
            "the right project folder."
        )
    old_start = content.index("  <!-- GAME SCREEN -->")
    old_end = content.index("  </section>", old_start) + len("  </section>")
    new_block = NEW_INDEX_HTML[
        NEW_INDEX_HTML.index("  <!-- GAME SCREEN -->"):
        NEW_INDEX_HTML.index("  </section>", NEW_INDEX_HTML.index("  <!-- GAME SCREEN -->")) + len("  </section>")
    ]
    patched = content[:old_start] + new_block + content[old_end:]
    path.write_text(patched, encoding="utf-8")
    print(f"  - {path.name}: patched")


def patch_style_css(path: Path) -> None:
    content = path.read_text(encoding="utf-8")
    if ALREADY_PATCHED_CSS_MARKER in content:
        print(f"  - {path.name}: already patched, skipping")
        return
    marker = "/* ---------- Game screen ---------- */"
    if marker not in content:
        raise SystemExit(
            f"ERROR: {path} doesn't look like the expected original file "
            "(couldn't find the old Game screen CSS section). Aborting."
        )
    old_start = content.index(marker)
    end_marker = "/* ---------- Player chips / mute ---------- */"
    if end_marker not in content:
        raise SystemExit(f"ERROR: {path} is missing an expected section boundary. Aborting.")
    old_end = content.index(end_marker)
    new_start = NEW_STYLE_CSS.index("/* ---------- Game screen")
    new_end = NEW_STYLE_CSS.index(end_marker)
    patched = content[:old_start] + NEW_STYLE_CSS[new_start:new_end] + content[old_end:]
    path.write_text(patched, encoding="utf-8")
    print(f"  - {path.name}: patched")


def patch_app_js(path: Path) -> None:
    content = path.read_text(encoding="utf-8")
    if ALREADY_PATCHED_JS_MARKER in content:
        print(f"  - {path.name}: already patched, skipping")
        return
    if APP_JS_SPLIT_MARKER not in content:
        raise SystemExit(
            f"ERROR: {path} doesn't look like the expected original file "
            "(couldn't find the offline round-sequence function). Aborting."
        )
    head = content[: content.index(APP_JS_SPLIT_MARKER)]
    new_head = NEW_APP_JS[: NEW_APP_JS.index(APP_JS_SPLIT_MARKER)]
    if head != new_head:
        print(
            "  ! warning: the shared top portion of app.js differs from what "
            "this patch expects (maybe you've made other edits there). "
            "Keeping your existing top portion and only replacing the "
            "table-rendering logic below it."
        )
    tail = NEW_APP_JS[NEW_APP_JS.index(APP_JS_SPLIT_MARKER):]
    patched = head + tail
    path.write_text(patched, encoding="utf-8")
    print(f"  - {path.name}: patched")


def main() -> None:
    print(f"Patching Chor Pulish project at: {ROOT}")
    index_html = ROOT / "index.html"
    style_css = ROOT / "css" / "style.css"
    app_js = ROOT / "js" / "app.js"

    for p in (index_html, style_css, app_js):
        if not p.exists():
            raise SystemExit(f"ERROR: expected file not found: {p}")

    patch_index_html(index_html)
    patch_style_css(style_css)
    patch_app_js(app_js)

    print("\nDone. Open index.html (or redeploy) to see the new circular table.")


if __name__ == "__main__":
    main()
